begin;
select plan(23);
insert into auth.users(id) values ('00000000-0000-0000-0000-0000000000a8'),('00000000-0000-0000-0000-0000000000b8');
select ok((select relrowsecurity from pg_class where oid='public.monthly_free_quota_claims'::regclass),'aylık hak tablosunda RLS açık');
select ok(not has_table_privilege('authenticated','public.monthly_free_quota_claims','insert'),'istemci hak kaydı yazamaz');
select ok(not has_function_privilege('anon','public.grant_monthly_free_quota(uuid,text,integer)','execute'),'anon RPC kapalı');
select ok(not has_function_privilege('authenticated','public.grant_monthly_free_quota(uuid,text,integer)','execute'),'authenticated RPC kapalı');
select ok(not has_function_privilege('service_role','public._grant_monthly_free_quota_at(uuid,text,integer,timestamptz)','execute'),'servis rolü ay/zaman seçemez');
select ok(has_function_privilege('service_role','public.grant_monthly_free_quota(uuid,text,integer)','execute'),'servis rolü DB saati RPC çağırabilir');
create temp table month_periods(label text,id uuid);
insert into month_periods select 'sep',(public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000a8',repeat('a',64),900,'2026-09-30 20:59:59+00')).id;
select is((select starts_at from public.quota_periods where id=(select id from month_periods where label='sep')),'2026-08-31 21:00:00+00'::timestamptz,'İstanbul Eylül başlangıcı UTC Ağustos');
select is((select ends_at from public.quota_periods where id=(select id from month_periods where label='sep')),'2026-09-30 21:00:00+00'::timestamptz,'Eylül son saniyesi doğru sınır');
select is((public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000a8',repeat('a',64),900,'2026-09-30 20:59:59+00')).id,null::uuid,'aynı ay tekrar false');
insert into month_periods select 'oct',(public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000a8',repeat('a',64),900,'2026-09-30 21:00:00+00')).id;
select isnt((select id from month_periods where label='oct'),null::uuid,'tam TR gece yarısında yeni hak');
select is((select starts_at from public.quota_periods where id=(select id from month_periods where label='oct')),'2026-09-30 21:00:00+00'::timestamptz,'UTC hâlâ Eylül olsa da Ekim hakkı');
select is((select ends_at from public.quota_periods where id=(select id from month_periods where label='oct')),'2026-10-31 21:00:00+00'::timestamptz,'31 günlük Ekim bitişi');
select is((select granted_seconds from public.quota_periods where id=(select id from month_periods where label='oct')),900,'önceki kullanılmamış 900 devretmez');
select is((public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000a8',repeat('b',64),900,'2026-10-15 00:00:00+00')).id,null::uuid,'aynı kullanıcı farklı kimlikle aynı ay hak alamaz');
select is((public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000b8',repeat('a',64),900,'2026-10-15 00:00:00+00')).id,null::uuid,'aynı kimlik farklı kullanıcı aynı ay hak alamaz');
insert into month_periods select 'leap',(public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000a8',repeat('a',64),900,'2028-02-29 12:00:00+00')).id;
select is((select ends_at-starts_at from public.quota_periods where id=(select id from month_periods where label='leap')),interval '29 days','artık yıl Şubat 29 gün');
insert into month_periods select 'year',(public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000a8',repeat('a',64),900,'2026-12-31 21:00:00+00')).id;
select is((select starts_at from public.quota_periods where id=(select id from month_periods where label='year')),'2026-12-31 21:00:00+00'::timestamptz,'yıl değişimi TR Ocak');
select throws_ok($$select public.grant_monthly_free_quota('00000000-0000-0000-0000-0000000000b8','bad',900)$$,'22023','invalid_identity_hash','bozuk hash reddedilir');
select throws_ok($$select public.grant_monthly_free_quota('00000000-0000-0000-0000-0000000000b8',repeat('c',64),0)$$,'22023','invalid_seconds','sıfır miktar reddedilir');
select is((select count(*)::int from public.quota_periods p where p.user_id='00000000-0000-0000-0000-0000000000a8' and starts_at<='2026-10-01 00:00:00+03' and ends_at>'2026-10-01 00:00:00+03'),1,'sınırda yalnız yeni dönem aktif');
delete from auth.users where id='00000000-0000-0000-0000-0000000000a8';
select is((select count(*)::int from public.monthly_free_quota_claims where identity_hash=repeat('a',64)),4,'hesap silinse de ay kayıtları kalır');
select is((public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000b8',repeat('a',64),900,'2026-10-20 00:00:00+00')).id,null::uuid,'aynı ay sil/recreate engellenir');
select isnt((public._grant_monthly_free_quota_at('00000000-0000-0000-0000-0000000000b8',repeat('a',64),900,'2026-11-01 00:00:00+03')).id,null::uuid,'sonraki ay aynı kimlik yeni hesapta hakkını alır');
select * from finish();
rollback;
